// ============================================================
// Tarjetas de sellos digitales — Worker principal
// Rutas:
//   GET  /brandpanel                -> login / crear tu cuenta / panel (según el caso)
//   POST /brandpanel/signup         -> crea tu cuenta (solo si todavía no existe ninguna)
//   POST /brandpanel/login          -> inicia sesión con correo y contraseña
//   GET  /brandpanel/logout         -> cierra tu sesión
//   POST /brandpanel/businesses     -> crea un negocio nuevo (protegido con tu sesión)
//   GET  /:slug/nuevo          -> formulario público para que el CLIENTE se registre solo
//   POST /:slug/nuevo          -> crea al cliente y lo manda directo a su tarjeta
//   GET  /:slug/:code          -> tarjeta del cliente
//   GET  /staff/:slug          -> pantalla de PIN o panel de sellado
//   POST /staff/:slug/login    -> valida el PIN, crea sesión
//   POST /staff/:slug/stamp    -> suma un sello a un cliente
//   POST /staff/:slug/register -> registra un cliente nuevo desde el panel (respaldo manual)
//   GET  /staff/:slug/clientes -> lista de todos los clientes registrados
//   GET  /staff/:slug/logout   -> cierra sesión
// ============================================================

import { createSign, createHash } from 'node:crypto';
import zlib from 'node:zlib';

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const parts = url.pathname.split('/').filter(Boolean);

    try {
      // ---- página de inicio de heytapp.com ----
      if (parts.length === 0) {
        return renderLandingPage();
      }
      if (parts.length === 1 && parts[0] === 'contacto' && request.method === 'POST') {
        return handleCreateLead(request, env);
      }
      if (parts.length === 1 && parts[0] === 'contacto' && request.method === 'GET') {
        return renderContactPage();
      }
      if (parts.length === 1 && parts[0] === 'solicitud' && request.method === 'POST') {
        return handleCreateLead(request, env);
      }
      if (parts.length === 1 && parts[0] === 'solicitud' && request.method === 'GET') {
        return renderSolicitudPage(url);
      }
      if (parts.length === 1 && parts[0] === 'confirmar-plan' && request.method === 'GET') {
        return handleConfirmarPlan(request, env, url);
      }
      if (parts.length === 1 && parts[0] === 'info-completa-x7k2m' && request.method === 'GET') {
        return await renderFullInfoPage(env, url);
      }
      if (parts.length === 1 && parts[0] === 'info' && request.method === 'GET') {
        return await renderFullInfoPage(env, url);
      }
      // ---- formulario de bienvenida para clientes que ya pagaron: /bienvenida/:codigo ----
      if (parts.length === 2 && parts[0] === 'bienvenida' && request.method === 'GET') {
        return await renderBienvenidaRoute(env, parts[1]);
      }
      if (parts.length === 2 && parts[0] === 'bienvenida' && request.method === 'POST') {
        return await handleBienvenidaSubmit(request, env, parts[1]);
      }
      if (parts.length === 1 && parts[0] === 'site-manifest.json') {
        const manifest = {
          name: 'Hey Tapp', short_name: 'Hey Tapp', start_url: '/', display: 'standalone',
          background_color: '#FDFBF2', theme_color: '#42281B',
          icons: [
            { src: '/icon-192.png', sizes: '192x192', type: 'image/png' },
            { src: '/icon-512.png', sizes: '512x512', type: 'image/png' },
          ],
        };
        return new Response(JSON.stringify(manifest), { headers: { 'Content-Type': 'application/manifest+json' } });
      }

      // ---- Apple Wallet ----
      // botón "Agregar a Apple Wallet" desde la tarjeta del cliente
      if (parts.length === 3 && parts[0] === 'wallet' && parts[1] !== 'v1') {
        return handleWalletDownload(env, parts[1], parts[2], url.origin);
      }
      // web service que exige Apple para poder actualizar tarjetas solas
      if (parts[0] === 'wallet' && parts[1] === 'v1') {
        // /wallet/v1/devices/:deviceId/registrations/:passTypeId/:serial
        if (parts[2] === 'devices' && parts[4] === 'registrations') {
          const deviceId = parts[3], passTypeId = parts[5], serial = parts[6];
          if (serial && request.method === 'POST') return handleWalletRegister(request, env, deviceId, passTypeId, serial);
          if (serial && request.method === 'DELETE') return handleWalletUnregister(env, deviceId, passTypeId, serial);
          if (!serial && request.method === 'GET') return handleWalletUpdatedSerials(env, deviceId, passTypeId);
        }
        // /wallet/v1/passes/:passTypeId/:serial
        if (parts[2] === 'passes' && parts[3] && parts[4] && request.method === 'GET') {
          return handleWalletGetPass(env, parts[3], parts[4], url.origin);
        }
        // /wallet/v1/log
        if (parts[2] === 'log' && request.method === 'POST') {
          return handleWalletLog(request);
        }
      }

      // ---- ícono de la app (para "agregar a inicio" en el celular) ----
      if (parts[0] === 'apple-touch-icon.png' || url.pathname === '/apple-touch-icon.png') {
        return servePngIcon(HEY_TAPP_ICON_180);
      }
      if (url.pathname === '/icon-192.png') return servePngIcon(HEY_TAPP_ICON_192);
      if (url.pathname === '/icon-512.png') return servePngIcon(HEY_TAPP_ICON_512);
      if (url.pathname === '/og-image.jpg') return serveJpgImage(HEY_TAPP_OG_IMAGE_BASE64);
      // manifest específico de la tarjeta de un cliente (para que "abrir" desde el
      // ícono lleve directo a SU tarjeta, con el nombre de SU negocio)
      if (parts.length === 3 && parts[2] === 'manifest.json') {
        return handleCardManifest(env, parts[0], parts[1]);
      }
      // manifest genérico (para el panel de staff)
      if (parts.length === 2 && parts[1] === 'manifest.json') {
        return handleStaffManifest(env, parts[0]);
      }

      // ---- tu panel de administración (My Tapp) ----
      if (parts[0] === 'brandpanel') {
        if (parts[1] === 'leads' && parts[2] && parts[3] === 'delete' && request.method === 'POST') return handleDeleteLead(request, env, parts[2]);
        if (parts[1] === 'leads' && parts[2] && parts[3] === 'emailed' && request.method === 'POST') return handleUpdateLeadEmailed(request, env, parts[2]);
        if (parts[1] === 'leads' && parts[2] === 'bienvenida-link' && request.method === 'POST') return handleGenerateBienvenidaLink(request, env, url);
        if (parts[1] === 'leads') return handleLeadsList(request, env);
        if (parts[1] === 'bienvenidas') return handleBienvenidaQueue(request, env);
        if (parts[1] === 'bienvenida-archivo' && parts[2]) return handleBienvenidaFile(request, env, parts.slice(2).join('/'));
        if (parts[1] === 'bienvenida-solicitud' && parts[2] && parts[3] === 'delete' && request.method === 'POST') return handleDeleteBienvenidaSubmission(request, env, parts[2]);
        if (parts[1] === 'signup' && request.method === 'POST') return handleAdminSignup(request, env);
        if (parts[1] === 'login' && request.method === 'POST') return handleAdminLogin(request, env);
        if (parts[1] === 'logout') return handleAdminLogout(request, env);
        if (parts[1] === 'recuperar' && request.method === 'POST') return handleAdminRecover(request, env);
        if (parts[1] === 'recuperar') { const pname = await getPlatformName(env); return new Response(renderAdminRecoverForm(pname), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } }); }
        if (parts[1] === 'cambiar-password' && request.method === 'POST') return handleAdminChangePassword(request, env);
        if (parts[1] === 'businesses' && request.method === 'POST') return handleCreateBusiness(request, env);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'edit') return handleEditBusinessForm(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'metrics') return handleBusinessMetrics(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'metrics-export') return handleBusinessMetricsExport(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'update' && request.method === 'POST') return handleUpdateBusiness(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'delete' && request.method === 'POST') return handleDeleteBusiness(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'unlock' && request.method === 'POST') return handleUnlockBusiness(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'reveal-pin' && request.method === 'POST') return handleRevealPin(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'update-pin-note' && request.method === 'POST') return handleUpdatePinNote(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'payment' && request.method === 'POST') return handleUpdatePayment(request, env, parts[2]);
        if (parts[1] === 'business' && parts[2] && parts[3] === 'toggle-suspend' && request.method === 'POST') return handleToggleSuspend(request, env, parts[2]);
        if (parts[1] === 'update-platform-name' && request.method === 'POST') return handleUpdatePlatformName(request, env);
        if (parts[1] === 'appearance' && request.method === 'POST') return handleUpdateAppearance(request, env);
        return handleAdminPage(request, env);
      }

      // ---- panel del staff ----
      if (parts[0] === 'staff' && parts[1]) {
        const slug = parts[1];
        if (parts[2] === 'login' && request.method === 'POST') return handleLogin(request, env, slug);
        if (parts[2] === 'stamp' && request.method === 'POST') return handleStamp(request, env, slug);
        if (parts[2] === 'register' && request.method === 'POST') return handleRegister(request, env, slug);
        if (parts[2] === 'clientes' && parts[3] === 'borrar-varios' && request.method === 'POST') return handleBulkDeleteCustomers(request, env, slug);
        if (parts[2] === 'clientes') return handleClientesList(request, env, slug);
        if (parts[2] === 'metricas') return handleBusinessMetrics(request, env, slug);
        if (parts[2] === 'metricas-export') return handleBusinessMetricsExport(request, env, slug);
        if (parts[2] === 'cliente' && parts[3] && parts[4] === 'delete' && request.method === 'POST') return handleDeleteCustomer(request, env, slug, parts[3]);
        if (parts[2] === 'historial' && parts[3]) return handleHistorial(request, env, slug, parts[3]);
        if (parts[2] === 'logout') return handleLogout(request, env, slug);
        return handleStaffPage(request, env, slug);
      }

      // ---- auto-registro público del cliente: /:slug/nuevo ----
      if (parts.length === 2 && parts[1] === 'nuevo') {
        if (request.method === 'POST') return handlePublicRegisterSubmit(request, env, parts[0]);
        return handlePublicRegisterForm(env, parts[0], url.origin);
      }

      // ---- tarjeta del cliente: /:slug/:code ----
      if (parts.length === 2) {
        return handleCustomerCard(env, parts[0], parts[1], url.origin);
      }

      return new Response('No encontrado', { status: 404 });
    } catch (err) {
      // el detalle real del error queda solo en tus logs de Cloudflare (Observability),
      // nunca en la respuesta que ve el navegador — así no se filtran nombres de
      // columnas, rutas internas, etc. a quien esté viendo la respuesta
      console.error('[error no manejado]', err && err.stack ? err.stack : err);
      const wantsJson = (request.headers.get('Content-Type') || '').includes('json') || request.method === 'POST';
      if (wantsJson) {
        return new Response(JSON.stringify({ error: 'Ocurrió un error del servidor. Intenta de nuevo en unos segundos.' }), { status: 500, headers: { 'Content-Type': 'application/json' } });
      }
      return new Response('Ocurrió un error del servidor. Intenta de nuevo en unos segundos.', { status: 500 });
    }
  },

  // se ejecuta solo, una vez al día, a la hora que se configure en
  // wrangler.jsonc (ver el bloque "triggers":{"crons":[...]}). No lo llama
  // nadie por su cuenta, ni una persona ni un botón — lo dispara Cloudflare.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(handleWinBackReminders(env));
  }
};

