async function handleCreateLead(request, env) {
  const rl = await checkRateLimit(env, request, 'lead', 8);
  const contentType = request.headers.get('content-type') || '';
  const isTraditionalForm = contentType.includes('application/x-www-form-urlencoded') || contentType.includes('multipart/form-data');

  if (!rl.ok) {
    if (isTraditionalForm) {
      return Response.redirect(new URL('/solicitud?error=rate', request.url).toString(), 302);
    }
    return new Response(JSON.stringify({ error: 'Demasiados intentos. Espera unos minutos e intenta de nuevo.' }), { status: 429, headers: { 'Content-Type': 'application/json' } });
  }

  let body;
  if (isTraditionalForm) {
    const formData = await request.formData();
    body = Object.fromEntries(formData.entries());
  } else {
    body = await request.json().catch(() => ({}));
  }

  const name = String(body.name || '').trim();
  const phone = digitsOnly(body.phone); // solo dígitos, sin regex
  const email = String(body.email || '').trim();
  const instagram = String(body.instagram || '').trim();
  const businessType = ['digital', 'fisico', 'wallet'].includes(body.business_type) ? body.business_type : null;
  const from = ['web', 'info'].includes(body.from) ? body.from : 'web';

  const fail = (msg) => {
    if (isTraditionalForm) {
      const back = new URL('/solicitud', request.url);
      back.searchParams.set('error', msg);
      if (businessType) back.searchParams.set('plan', businessType);
      back.searchParams.set('from', from);
      return Response.redirect(back.toString(), 302);
    }
    return new Response(JSON.stringify({ error: msg }), { status: 400, headers: { 'Content-Type': 'application/json' } });
  };

  if (!name || !phone || !email || !instagram) {
    return fail('Faltan datos: nombre, celular, correo e Instagram son obligatorios');
  }
  if (name.length > 80) {
    return fail('El nombre es demasiado largo (máximo 80 caracteres)');
  }
  if (phone.length === 0) {
    return fail('El celular debe tener solo números');
  }
  if (!looksLikeEmail(email)) {
    return fail('Ese correo no parece válido');
  }

  // se intenta guardar en la base de datos, pero si algo falla aquí (por
  // ejemplo, si todavía no corriste la migración de la tabla "leads") no
  // debe tumbar el envío completo — igual intentamos mandar el correo.
  let leadId = null;
  try {
    const { meta } = await env.DB.prepare(
      'INSERT INTO leads (name, phone, email, instagram, business_type) VALUES (?, ?, ?, ?, ?)'
    ).bind(name, phone, email, instagram || null, businessType).run();
    leadId = meta.last_row_id;
  } catch (dbErr) {
    // seguimos igual: la solicitud se manda por correo aunque no se haya podido guardar
  }

  const planLabel = businessType === 'digital' ? 'Plan Fideliza Digital'
    : businessType === 'fisico' ? 'Plan Fideliza Físico'
    : businessType === 'wallet' ? 'Plan Fideliza Wallet' : 'No especificó';
  const emailSubject = from === 'info'
    ? `🎉 ¡Quiere contratar! ${planLabel} — ${name}`
    : `Nueva solicitud de info — ${name}`;

  // si el navegador de la persona ya logró mandarlo directo a FormSubmit,
  // no hace falta que el servidor reintente. Si no, el servidor lo intenta
  // por su cuenta, empezando por el canal más confiable (Resend).
  let emailed = body.emailed === true;

  // opción 1: Resend (el canal confiable, hecho para envíos automáticos)
  if (!emailed && env.RESEND_API_KEY) {
    try {
      const res = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${env.RESEND_API_KEY}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          from: 'Hey Tapp <hola@heytapp.com>',
          to: ['hola@heytapp.com'],
          reply_to: email,
          subject: emailSubject,
          text: `Nueva solicitud desde heytapp.com\n\nNombre: ${name}\nCelular: ${phone}\nCorreo: ${email}\nInstagram del negocio: ${instagram || '—'}\nInteresado en: ${planLabel}`,
        }),
      });
      emailed = res.ok;
      if (!emailed) {
        const errBody = await res.text().catch(() => '');
        console.log('[handleCreateLead] Resend respondió con error. status:', res.status, 'body:', errBody);
      }
    } catch (err) {
      emailed = false;
      console.log('[handleCreateLead] error de red con Resend:', err && err.message);
    }
  }

  // opción 2: FormSubmit (respaldo, por si Resend no está configurado o falló)
  if (!emailed) {
    try {
      const res = await fetch('https://formsubmit.co/ajax/hola@heytapp.com', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({
          nombre: name, celular: phone, correo: email, instagram: instagram || '—', interesado_en: planLabel,
          _subject: emailSubject,
          _template: 'table',
        }),
      });
      // un 200 OK no garantiza que se haya mandado el correo de verdad,
      // hay que confirmar el JSON de éxito
      const contentType = res.headers.get('content-type') || '';
      if (res.ok && contentType.includes('application/json')) {
        const data = await res.json().catch(() => null);
        emailed = !!(data && (data.success === 'true' || data.success === true));
        if (!emailed) console.log('[handleCreateLead] FormSubmit respondió OK pero sin éxito confirmado:', JSON.stringify(data));
      } else {
        emailed = false;
        console.log('[handleCreateLead] FormSubmit no devolvió JSON. status:', res.status, 'content-type:', contentType);
      }
    } catch (err) {
      emailed = false;
      console.log('[handleCreateLead] error de red con FormSubmit:', err && err.message);
    }
  }

  // opción 3: Formspree, si lo tienes configurado
  if (!emailed && env.FORMSPREE_FORM_ID) {
    try {
      const res = await fetch(`https://formspree.io/f/${env.FORMSPREE_FORM_ID}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({
          name, phone, email, instagram: instagram || '—', interesado_en: planLabel,
          _subject: emailSubject,
          _replyto: email,
        }),
      });
      emailed = res.ok;
    } catch (err) {
      emailed = false;
    }
  }

  if (emailed && leadId) {
    try {
      await env.DB.prepare('UPDATE leads SET emailed = 1 WHERE id = ?').bind(leadId).run();
    } catch (dbErr) {
      // no pasa nada si esto falla, el correo ya se envió de todas formas
    }
  }

  if (isTraditionalForm) {
    let dest;
    if (from === 'info') {
      dest = new URL(`/solicitud?gracias=1&from=info&plan=${businessType || ''}`, request.url);
    } else {
      dest = new URL('https://heytapp.com/info-completa-x7k2m');
      if (leadId) dest.searchParams.set('lead', leadId);
    }
    return Response.redirect(dest.toString(), 302);
  }

  return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
}

// ------------------------------------------------------------
// formulario de bienvenida (/bienvenida/:codigo): lo llena el cliente
// después de pagar. No crea el negocio solo, guarda todo en
// onboarding_submissions como una bandeja, y Anaelí la convierte en
// negocio real desde el admin cuando la revisa.
// ------------------------------------------------------------

async function renderBienvenidaRoute(env, code) {
  let row = null;
  try {
    row = await env.DB.prepare('SELECT * FROM onboarding_submissions WHERE code = ?').bind(code).first();
  } catch (err) {
    console.error('[bienvenida] error buscando código', err && err.message);
  }

  if (!row) {
    return new Response(renderBienvenidaNotFoundPage(), {
      status: 404,
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  if (row.submitted_at) {
    return new Response(renderBienvenidaThanksPage(row.business_name), {
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  return new Response(renderBienvenidaFormPage(code, row.plan), {
    headers: { 'Content-Type': 'text/html; charset=UTF-8' },
  });
}

async function handleBienvenidaSubmit(request, env, code) {
  let row = null;
  try {
    row = await env.DB.prepare('SELECT * FROM onboarding_submissions WHERE code = ?').bind(code).first();
  } catch (err) {
    console.error('[bienvenida] error buscando código', err && err.message);
  }

  if (!row) {
    return new Response(renderBienvenidaNotFoundPage(), {
      status: 404,
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  if (row.submitted_at) {
    return new Response(renderBienvenidaThanksPage(row.business_name), {
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  const plan = row.plan;

  let formData;
  try {
    formData = await request.formData();
  } catch (err) {
    return new Response(renderBienvenidaFormPage(code, plan, 'No pudimos leer el formulario. Intenta de nuevo.'), {
      status: 400,
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  const str = (v, max) => (v == null ? '' : String(v).trim().slice(0, max));
  const businessName = str(formData.get('business_name'), 120);
  const totalStampsRaw = parseInt(formData.get('total_stamps'), 10);
  // el formulario del cliente tope en 10 sellos (el límite general del
  // sistema en 50 sigue existiendo, pero solo Anaelí puede pasar de 10
  // editando el negocio desde el admin)
  const totalStamps = Number.isFinite(totalStampsRaw) ? Math.max(3, Math.min(10, totalStampsRaw)) : null;
  const reward = str(formData.get('reward'), 120);
  const greeting = str(formData.get('greeting'), 120);
  const instagramUser = str(formData.get('instagram_user'), 60);
  const instagramLink = str(formData.get('instagram_link'), 200);
  const stampIdea = str(formData.get('stamp_idea'), 300);

  // campos que solo aplican según el plan
  const habladorAddress = plan === 'fisico' ? str(formData.get('hablador_address'), 200) : '';
  const mapsLink = plan === 'wallet' ? str(formData.get('maps_link'), 300) : '';
  const sellsMode = plan === 'wallet' ? str(formData.get('sells_mode'), 20) : '';

  const stampIconFile = formData.get('stamp_icon');
  const hasStampIconFile = stampIconFile && typeof stampIconFile === 'object' && typeof stampIconFile.arrayBuffer === 'function' && stampIconFile.size > 0;

  const missingCommon = !businessName || !totalStamps || !reward;
  const missingStampInfo = !hasStampIconFile && !stampIdea;
  const missingFisico = plan === 'fisico' && !habladorAddress;
  const missingWallet = plan === 'wallet' && !sellsMode;

  if (missingCommon || missingStampInfo || missingFisico || missingWallet) {
    const msg = missingStampInfo && !missingCommon
      ? 'Cuéntanos algo sobre el sello: sube una imagen o descríbenos una idea, aunque sea breve.'
      : 'Faltan datos obligatorios, revisa el formulario e intenta de nuevo.';
    return new Response(renderBienvenidaFormPage(code, plan, msg), {
      status: 400,
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  // el logo y la imagen de paleta se suben a R2, no a la base de datos:
  // así D1 se queda liviano sin importar cuántos negocios se agreguen
  const uploadToR2 = async (file, folder) => {
    if (!file || typeof file !== 'object' || typeof file.arrayBuffer !== 'function' || !file.size) return null;
    if (!env.LOGOS_BUCKET) {
      console.error('[bienvenida] LOGOS_BUCKET no está conectado, no se pudo guardar el archivo');
      return null;
    }
    // solo imágenes, máximo 8 MB, para no dejar que cualquier archivo
    // se cuele al bucket y se coma tu espacio de R2
    const allowedTypes = ['image/png', 'image/jpeg', 'image/jpg'];
    if (!allowedTypes.includes(file.type)) {
      console.log(`[bienvenida] archivo rechazado por tipo no permitido (${folder}):`, file.type);
      return { error: 'tipo' };
    }
    const MAX_BYTES = 8 * 1024 * 1024;
    if (file.size > MAX_BYTES) {
      console.log(`[bienvenida] archivo rechazado por tamaño (${folder}):`, file.size);
      return { error: 'tamano' };
    }
    const ext = file.type === 'image/jpeg' || file.type === 'image/jpg' ? 'jpg' : 'png';
    const key = `${folder}/${code}-${Date.now()}.${ext}`;
    try {
      // solo se guarda el archivo tal cual, sin procesarlo, para no
      // acercarse al límite de tiempo de procesamiento del plan gratis
      await env.LOGOS_BUCKET.put(key, file.stream(), {
        httpMetadata: { contentType: file.type || 'image/png' },
      });
      return key;
    } catch (err) {
      console.error(`[bienvenida] error subiendo archivo a R2 (${folder})`, err && err.message);
      return null;
    }
  };

  const logoResult = await uploadToR2(formData.get('logo'), 'logos');
  const paletteResult = await uploadToR2(formData.get('palette_image'), 'paletas');
  const stampIconResult = hasStampIconFile ? await uploadToR2(stampIconFile, 'sellos') : null;
  // el fondo de los sellos aplica a todos los planes (fondo del área de
  // sellos en la tarjeta web); si el plan incluye Wallet, se reutiliza ahí también
  const stripBgResult = await uploadToR2(formData.get('strip_bg_image'), 'fondos');

  // si algún archivo fue rechazado (tipo o tamaño), avisamos y no se guarda nada
  const uploadResults = [logoResult, paletteResult, stampIconResult, stripBgResult];
  const rejected = uploadResults.find(r => r && typeof r === 'object' && r.error);
  if (rejected) {
    const msg = rejected.error === 'tamano'
      ? 'Una de las imágenes pesa demasiado (máximo 8 MB). Intenta con una más liviana.'
      : 'Una de las imágenes no es un archivo válido (solo se aceptan PNG o JPG).';
    return new Response(renderBienvenidaFormPage(code, plan, msg), {
      status: 400,
      headers: { 'Content-Type': 'text/html; charset=UTF-8' },
    });
  }

  const logoKey = typeof logoResult === 'string' ? logoResult : null;
  const paletteKey = typeof paletteResult === 'string' ? paletteResult : null;
  const stampIconKey = typeof stampIconResult === 'string' ? stampIconResult : null;
  const stripBgKey = typeof stripBgResult === 'string' ? stripBgResult : null;

  try {
    await env.DB.prepare(
      `UPDATE onboarding_submissions
       SET business_name = ?, logo_key = ?, palette_image_key = ?,
           total_stamps = ?, reward = ?, greeting = ?, instagram_user = ?,
           instagram_link = ?, maps_link = ?, sells_mode = ?, hablador_address = ?,
           stamp_idea = ?, stamp_icon_key = ?, strip_bg_image_key = ?,
           submitted_at = datetime('now')
       WHERE code = ?`
    ).bind(
      businessName, logoKey, paletteKey,
      totalStamps, reward, greeting || null, instagramUser || null,
      instagramLink || null, mapsLink || null, sellsMode || null, habladorAddress || null,
      stampIdea || null, stampIconKey, stripBgKey,
      code
    ).run();
  } catch (err) {
    console.error('[bienvenida] error guardando en D1', err && err.message);
    return new Response('Ocurrió un error guardando tu información. Intenta de nuevo en unos segundos.', { status: 500 });
  }

  // aviso por correo, sin bloquear la respuesta al cliente si falla
  notifyBienvenidaSubmitted(env, { code, businessName }).catch(() => {});

  return new Response(renderBienvenidaThanksPage(businessName), {
    headers: { 'Content-Type': 'text/html; charset=UTF-8' },
  });
}

async function notifyBienvenidaSubmitted(env, { code, businessName }) {
  if (!env.RESEND_API_KEY) return;
  try {
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${env.RESEND_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: 'Hey Tapp <hola@heytapp.com>',
        to: ['hola@heytapp.com'],
        subject: `🎉 Nueva solicitud de bienvenida: ${businessName}`,
        text: `El código ${code} completó su formulario de bienvenida.\n\nMarca: ${businessName}\n\nRevísala en tu bandeja de solicitudes de bienvenida dentro del admin.`,
      }),
    });
    if (!res.ok) {
      const errBody = await res.text().catch(() => '');
      console.log('[bienvenida] Resend respondió con error. status:', res.status, 'body:', errBody);
    }
  } catch (err) {
    console.log('[bienvenida] error de red con Resend:', err && err.message);
  }
}

