function planLabelBienvenida(plan) {
  if (plan === 'digital') return 'Plan Fideliza Digital';
  if (plan === 'fisico') return 'Plan Fideliza Físico';
  if (plan === 'wallet') return 'Plan Fideliza Wallet';
  return '';
}

