async function renderFullInfoPage(env, url) {
  const leadIdRaw = url ? url.searchParams.get('lead') : null;
  let knownLead = null;
  if (leadIdRaw && env) {
    try {
      knownLead = await env.DB.prepare('SELECT id FROM leads WHERE id = ?').bind(leadIdRaw).first();
    } catch (e) {
      knownLead = null;
    }
  }
  const leadId = knownLead ? knownLead.id : null;
  const planBtnHref = (plan) => leadId
    ? `/confirmar-plan?lead=${leadId}&plan=${plan}`
    : `/solicitud?from=info&plan=${plan}`;

  const generalBenefits = [
    [icons.palette, 'Tarjeta de fidelidad <span class="hl">100% personalizada</span> con la identidad de tu marca'],
    [icons.target, 'Premio y cantidad de sellos <span class="hl">configurables</span>'],
    [icons.scan, 'Registro de sellos mediante <span class="hl">QR o código manual</span>'],
    [icons.key, '<span class="hl">Código único</span> para identificar a cada cliente'],
    [icons.staff, 'Panel para tu staff con <span class="hl">modo caja incluido</span>, para registrar los sellos de cada cliente'],
    [icons.wallet, '<span class="hl">Actualización automática</span> de la tarjeta'],
    [icons.chart, '<span class="hl">Historial de sellos</span> y actividad de tus clientes'],
    [icons.instagram, 'Botón directo al <span class="hl">Instagram</span> de tu negocio'],
    [icons.cap, 'Capacitación inicial y actualizaciones de la plataforma incluidas'],
  ];

  const generalBenefitsListHtml = generalBenefits.map(([icon, text]) => `<li><span class="deck-check-icon">${icon}</span><span>${text}</span></li>`).join('');

  const metricsBlock = (isWallet) => `
            <p class="folder-includes-label" style="margin-top:18px;">Conoce cómo están respondiendo tus clientes</p>
            <p class="folder-block-desc" style="margin:-2px 0 12px;">Accede a un panel de métricas para conocer el movimiento de tu programa de fidelidad.</p>
            <ul class="folder-extras">
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.chart}</span><span>Consulta cuántos clientes se han registrado.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.gift}</span><span>Revisa los premios canjeados y el promedio de sellos por cliente.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.scan}</span><span>Exporta toda tu base de clientes en formato CSV.</span></li>
              ${isWallet ? `<li><span class="deck-check-icon deck-check-icon-extra">${icons.sparkle}</span><span>Identifica a quienes llevan 14 días sin visitar tu negocio.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.wallet}</span><span>Conoce cuántos clientes tienen su tarjeta activa en Apple Wallet.</span></li>` : ''}
            </ul>`;

  const slide = (bg, cardBg, content, id) => `
  <section class="slide" id="${id}" style="background:${bg};">
    <div class="slide-card" style="background:${cardBg};">
      ${content}
    </div>
  </section>`;

  const folderTab = (plan, tabColor, tabText, icon, label, active) => `
        <div role="button" tabindex="0" class="folder-tab${active ? ' active' : ''}" data-plan="${plan}" style="--tab:${tabColor};--tab-text:${tabText};">
          <span class="folder-tab-icon">${icon}</span>
          <span class="folder-tab-label">${label}</span>
        </div>`;

  const folderPage = (plan, tabColor, tabText, icon, title, desc, differentiator, priceUno, priceMes, active) => `
      <div class="folder-page${active ? ' active' : ''}" data-plan="${plan}">
        <div class="folder-block folder-block-head">
          <span class="folder-plan-icon" style="background:${tabColor};color:${tabText};">${icon}</span>
          <h2>${title}</h2>
          <p>${desc}</p>
        </div>
        <div class="folder-divider"></div>
        <div class="hero-price-block">
          <div class="hero-price">${priceMes}<span class="hero-price-suffix">/mes</span></div>
          <p class="hero-price-note">Desde el segundo mes.<br><span class="hl">Tu primer mes es totalmente gratis.</span></p>
        </div>
        <div class="folder-block" style="margin-top:20px;">
          ${differentiator}
        </div>
        <div class="folder-divider"></div>
        <div class="setup-box">
          <span class="folder-pill">Pago único de implementación</span>
          <div class="setup-price">${priceUno}<span class="folder-price-suffix"> una sola vez</span></div>
          <p class="folder-block-desc">Incluye la creación, personalización y configuración de tu tarjeta para dejarla lista para usar, además de <span class="hl">tu primer mes de servicio totalmente gratis</span>. El pago mensual comienza a partir del segundo mes.</p>
        </div>
        <div class="folder-divider"></div>
        <p class="folder-note">El servicio se paga antes de iniciar cada mes.</p>
      </div>`;

  return new Response(`<!DOCTYPE html>
<html lang="es">
${pageHead(
  'Información completa, Hey Tapp',
  'Todo sobre Hey Tapp: qué incluye y los 3 planes, con precios reales.',
  'https://heytapp.com/info-completa-x7k2m',
  true
)}
<body class="deck-body">

  <a class="deck-explore" href="/" target="_blank" rel="noopener">Explorar heytapp.com →</a>

  <nav class="deck-dots">
    <a href="#s1" class="dot" data-label="Inicio"></a>
    <a href="#s2" class="dot" data-label="Tu tarjeta"></a>
    <a href="#s3" class="dot" data-label="Los 3 planes"></a>
    <a href="#s4" class="dot" data-label="Listo"></a>
  </nav>

  <main class="deck">

    ${slide('var(--terracotta)', 'var(--cream)', `
      <img src="data:image/png;base64,${HEY_TAPP_LOGO_BASE64}" alt="Hey Tapp" class="deck-logo deck-logo-big">
      <p class="deck-eyebrow-title">Planes disponibles</p>
      <h1 class="deck-hero-title">Dale a tus clientes<br>una razón para volver</h1>
      <p class="deck-hero-lead">Haz que esa primera compra no sea la última. Con Hey Tapp, tus clientes acumulan sellos, se acercan a un premio y tienen una razón más para seguir eligiendo tu marca.</p>
      <img src="data:image/png;base64,${HEY_TAPP_MASCOT_BASE64}" alt="" class="deck-mascot">
      <a href="#s2" class="deck-next">Ver tu tarjeta ↓</a>
    `, 's1')}

    ${slide('var(--pale-blue)', 'var(--cream)', `
      <span class="plan-tag-solo">Así es tu Hey Tapp</span>
      <h2>Una tarjeta digital para tu negocio</h2>
      <p class="plan-desc">Tus clientes acumulan sellos y ven su progreso en tiempo real, sin instalar nada.</p>
      <img src="data:image/png;base64,${HEY_TAPP_DUO_PHONES_BASE64}" alt="Tarjeta Hey Tapp en la web y en Apple Wallet" class="duo-phones">
      <a href="#s3" class="deck-next">Ver los 3 planes ↓</a>
    `, 's2')}

    <section class="slide" id="s3" style="background:var(--pale-blue);">
      <div class="folder-wrap">
        <div class="folder-intro">
          <span class="plan-tag-solo">Elige tu camino</span>
          <h2>Elige el plan ideal para tu negocio</h2>
        </div>
        <div class="folder-tabs">
          ${folderTab('digital', 'var(--mustard)', 'var(--brown)', icons.instagram, 'Digital', true)}
          ${folderTab('fisico', 'var(--blue)', 'var(--brown)', icons.shop, 'Físico', false)}
          ${folderTab('wallet', 'var(--terracotta)', 'var(--cream)', icons.wallet, 'Wallet', false)}
        </div>
        <div class="folder-body">
          ${folderPage('digital', 'var(--mustard)', 'var(--brown)', icons.instagram,
            'Plan Fideliza Digital',
            'Para marcas que venden por Instagram, WhatsApp o canales digitales',
            `<p class="folder-block-desc">Tu tarjeta se comparte mediante un <span class="hl">enlace directo</span> por Instagram, WhatsApp o cualquier canal digital.</p>
            <p class="folder-includes-label" style="margin-top:18px;">Tu tarjeta incluye:</p>
            <ul class="folder-universal">${generalBenefitsListHtml}</ul>`,
            '$45', '$13',
            true
          )}
          ${folderPage('fisico', 'var(--blue)', 'var(--brown)', icons.shop,
            'Plan Fideliza Físico',
            'Para marcas con tienda, local o punto de venta físico',
            `<p class="folder-includes-label">Todo lo que incluye el Plan Digital, más:</p>
            <p class="wallet-hook">Tu Hey Tapp, siempre visible en tu punto de venta.</p>
            <ul class="folder-extras">
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.scan}</span><span>Hablador físico personalizado con el QR único de tu negocio.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.target}</span><span>Tus clientes pueden escanearlo, registrarse y abrir su tarjeta al momento de pagar.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.shop}</span><span>El acceso permanece disponible en caja para cada cliente que visite tu local.</span></li>
            </ul>
            ${metricsBlock(false)}`,
            '$65', '$29',
            false
          )}
          ${folderPage('wallet', 'var(--terracotta)', 'var(--cream)', icons.wallet,
            'Plan Fideliza Wallet',
            'Para marcas que quieren llevar su fidelización un paso más allá',
            `<p class="folder-includes-label">Todo lo que incluye el Plan Digital, más Apple Wallet.</p>
            <ul class="folder-extras">
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.wallet}</span><span>Tus clientes pueden agregar su tarjeta directamente a Apple Wallet. Quienes no utilicen esta opción pueden continuar accediendo desde la web.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.scan}</span><span>Si tienes un punto de venta físico, también recibes tu hablador personalizado.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.pin}</span><span>Su tarjeta puede aparecer en la pantalla de bloqueo cuando está cerca de tu local, recordándole que puede utilizarla.</span></li>
              <li><span class="deck-check-icon deck-check-icon-extra">${icons.sparkle}</span><span>Si no visita el negocio durante 14 días, puede recibir una notificación invitándolo a volver.</span></li>
            </ul>
            ${metricsBlock(true)}`,
            '$90', '$59',
            false
          )}
        </div>
        <a href="#s4" class="deck-next" style="display:block;text-align:center;margin-top:16px;">Listo ↓</a>
      </div>
    </section>

    ${slide('var(--terracotta)', 'var(--cream)', `
      <img src="data:image/png;base64,${HEY_TAPP_MONO_TERRACOTTA_BASE64}" alt="Hey Tapp" class="deck-logo-mono">
      <p class="deck-closing">Actualizamos la interfaz constantemente para que vivas la mejor experiencia junto con tus clientes.</p>
      <p class="deck-choose">¿Cuál plan eliges?</p>
      <div class="deck-plan-buttons">
        <a href="${planBtnHref('digital')}" class="deck-plan-btn" style="--btn-color:var(--mustard);">Quiero el Plan Digital</a>
        <a href="${planBtnHref('fisico')}" class="deck-plan-btn" style="--btn-color:var(--blue);">Quiero el Plan Físico</a>
        <a href="${planBtnHref('wallet')}" class="deck-plan-btn" style="--btn-color:var(--terracotta);color:var(--cream);">Quiero el Plan Wallet</a>
      </div>
      <p class="deck-credit">Una marca de <a href="https://www.instagram.com/anaeli.brand" target="_blank" rel="noopener">Anaelí Brand</a></p>
    `, 's4')}

  </main>

  <style>
    html, body.deck-body{margin:0;}
    .deck{scroll-behavior:smooth;}
    .slide{scroll-snap-align:start;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:30px;box-sizing:border-box;position:relative;}
    .slide-card{max-width:600px;width:100%;border-radius:28px;padding:44px 38px;box-shadow:0 20px 60px rgba(0,0,0,.25);text-align:center;color:var(--brown);}
    .deck-logo{height:38px;margin-bottom:22px;}
    .deck-logo-big{height:64px;display:block;margin:0 auto 26px;}
    .deck-eyebrow-title{font-family:'Baloo 2',sans-serif;font-size:clamp(20px,4vw,28px);font-weight:800;color:var(--terracotta);text-transform:uppercase;letter-spacing:.03em;margin:0 0 10px;}
    .deck-hero-title{font-family:'Baloo 2',sans-serif;font-size:clamp(26px,5vw,38px);margin:0 0 16px;line-height:1.15;}
    .deck-hero-lead{font-size:15.5px;line-height:1.6;color:#6B5645;margin:0 0 22px;}
    .deck-mascot{max-width:170px;margin:0 auto 22px;display:block;}
    .duo-phones{display:block;width:100%;max-width:340px;height:auto;margin:18px auto 6px;}
    .plan-tag-solo{display:inline-block;background:rgba(176,71,46,.1);color:var(--terracotta);font-size:12px;font-weight:700;padding:5px 14px;border-radius:99px;margin-bottom:14px;}
    .slide-card h2{font-family:'Baloo 2',sans-serif;font-size:clamp(20px,3.4vw,26px);margin:0 0 12px;line-height:1.2;text-align:left;}
    .plan-desc{font-size:14.5px;line-height:1.6;color:#6B5645;margin:0 0 20px;text-align:left;}
    .hl{color:var(--terracotta);font-weight:800;}
    .deck-check-icon{flex:0 0 auto;width:26px;height:26px;border-radius:8px;background:rgba(176,71,46,.1);color:var(--terracotta);display:flex;align-items:center;justify-content:center;}
    .deck-check-icon svg{width:14px;height:14px;}
    .deck-next{display:inline-block;margin-top:18px;font-size:13px;font-weight:700;color:var(--terracotta);text-decoration:none;}
    .deck-closing{font-size:16px;line-height:1.6;max-width:420px;margin:0 auto 26px;}
    .deck-logo-mono{height:52px;width:auto;margin:0 auto 22px;display:block;}
    .deck-choose{font-family:'Baloo 2',sans-serif;font-size:20px;color:var(--terracotta);margin:0 0 16px;}
    .deck-plan-buttons{display:flex;flex-direction:column;gap:10px;margin:0 0 24px;}
    .deck-plan-btn{display:block;background:var(--btn-color);color:var(--brown);text-decoration:none;font-weight:800;font-size:14px;padding:13px 20px;border-radius:12px;text-align:center;box-shadow:0 6px 16px rgba(66,40,27,.18);transition:transform .15s ease;}
    .deck-plan-btn:hover{transform:translateY(-1px);}
    .deck-explore-btn{display:inline-block;background:var(--brown);color:var(--cream);text-decoration:none;padding:14px 26px;border-radius:12px;font-weight:800;font-size:15px;margin-bottom:22px;}
    .deck-credit{font-size:12.5px;color:#6B5645;}
    .deck-credit a{color:inherit;}
    .deck-explore{position:fixed;top:16px;right:16px;z-index:20;background:rgba(253,251,242,.92);color:var(--brown);text-decoration:none;font-size:12.5px;font-weight:700;padding:8px 14px;border-radius:99px;box-shadow:0 3px 10px rgba(0,0,0,.15);}
    .deck-dots{position:fixed;right:20px;top:50%;transform:translateY(-50%);z-index:20;display:flex;flex-direction:column;gap:12px;}
    .dot{width:9px;height:9px;border-radius:50%;background:rgba(66,40,27,.25);display:block;position:relative;}
    .dot.active{background:var(--terracotta);}
    .dot:hover:after{content:attr(data-label);position:absolute;right:18px;top:50%;transform:translateY(-50%);background:var(--brown);color:var(--cream);font-size:11px;padding:4px 8px;border-radius:6px;white-space:nowrap;}

    /* ---- carpeta con pestañas ---- */
    .folder-wrap{max-width:560px;width:100%;padding:6px;}
    .folder-intro{text-align:center;margin-bottom:18px;}
    .folder-intro h2{text-align:center;}
    .folder-tabs{display:flex;align-items:stretch;gap:6px;padding:0 6px;}
    .folder-tab{position:static!important;flex:1;width:auto;box-shadow:0 -2px 8px rgba(66,40,27,.08);font-size:12px;background:color-mix(in srgb, var(--tab) 40%, var(--cream));border-radius:16px 16px 0 0;padding:14px 6px 16px;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;transition:background .2s;font-family:Manrope,sans-serif;border:1.5px solid rgba(66,40,27,.18);border-bottom:none;}
    .folder-tab.active{background:var(--tab);}
    .folder-tab-icon{position:static!important;width:26px;height:26px;border-radius:8px;background:rgba(253,251,242,.7);display:flex;align-items:center;justify-content:center;color:var(--brown);}
    .folder-tab.active .folder-tab-icon{color:var(--tab-text);}
    .folder-tab-icon svg{width:15px;height:15px;}
    .folder-tab-label{position:static!important;font-size:12px;font-weight:700;color:var(--brown);}
    .folder-tab.active .folder-tab-label{color:var(--tab-text);}
    .folder-body{position:relative!important;display:block!important;background:var(--cream);border-radius:0 20px 20px 20px;padding:34px 26px 30px;box-shadow:0 20px 50px rgba(0,0,0,.22);border:1px solid rgba(66,40,27,.08);}
    .folder-page{display:none;}
    .folder-page.active{display:block;}
    .folder-block{text-align:left;}
    .folder-block-head{text-align:center;}
    .folder-plan-icon{position:static!important;display:inline-flex;width:44px;height:44px;border-radius:13px;align-items:center;justify-content:center;margin-bottom:12px;}
    .folder-plan-icon svg{width:24px;height:24px;}
    .folder-block-head h2{font-size:19px;margin:0 0 8px;text-align:center;}
    .folder-block-head p{font-size:13.5px;color:#6B5645;margin:0;}
    .folder-divider{border-top:1px dashed rgba(66,40,27,.2);margin:18px 0;}
    .folder-includes-label{font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.02em;color:#6B5645;margin:0 0 10px;}
    .wallet-hook{font-family:'Baloo 2',sans-serif;font-size:16px;color:var(--terracotta);margin:12px 0 14px;line-height:1.3;}
    .folder-universal{list-style:none;margin:0;padding:0;text-align:left;}
    .folder-universal li{font-size:13px;line-height:1.45;padding:8px 0;display:flex;align-items:flex-start;gap:10px;}
    .folder-universal .deck-check-icon{width:22px;height:22px;flex-shrink:0;margin-top:1px;}
    .folder-universal .deck-check-icon svg{width:12px;height:12px;}
    .folder-extras{list-style:none;margin:0;padding:0;text-align:left;}
    .folder-extras li{font-size:13px;line-height:1.45;padding:7px 0;display:flex;align-items:flex-start;gap:10px;}
    .folder-extras .deck-check-icon{width:22px;height:22px;flex-shrink:0;margin-top:1px;}
    .folder-extras .deck-check-icon svg{width:12px;height:12px;}
    .deck-check-icon-extra{background:rgba(176,71,46,.16)!important;}
    .folder-pill{display:inline-block;background:rgba(176,71,46,.12);color:var(--terracotta);font-size:16px;font-weight:800;padding:8px 18px;border-radius:99px;margin-bottom:12px;}
    .folder-price-suffix{font-family:Manrope,sans-serif;font-size:13px;color:#6B5645;font-weight:600;}
    .folder-block-desc{font-size:13.5px;line-height:1.6;color:#6B5645;margin:0;}
    .folder-note{font-size:12px;color:#6B5645;text-align:center;margin:0;}

    /* ---- precio mensual primero ---- */
    .hero-price-block{text-align:center;background:rgba(176,71,46,.06);border-radius:18px;padding:20px 16px;}
    .hero-price{font-family:'Baloo 2',sans-serif;font-size:44px;color:var(--terracotta);line-height:1;}
    .hero-price-suffix{font-family:Manrope,sans-serif;font-size:16px;color:var(--brown);font-weight:700;}
    .hero-price-note{font-size:13px;color:#6B5645;margin:8px 0 0;line-height:1.5;}
    .setup-box{background:rgba(66,40,27,.04);border-radius:16px;padding:18px 18px 16px;}
    .setup-price{font-family:'Baloo 2',sans-serif;font-size:38px;color:var(--brown);margin-bottom:10px;line-height:1.2;}

    /* ---- celular en línea con logo + títulos ---- */
    .phone-outline-wrap{margin:22px auto 6px;max-width:260px;}
    .showcase-title{min-height:44px;display:flex;align-items:center;justify-content:center;margin-bottom:14px;position:relative;}
    .showcase-title-logo, .showcase-title-text{position:absolute;left:0;right:0;opacity:0;transition:opacity .5s ease;text-align:center;}
    .showcase-title-logo{height:28px;width:auto;margin:0 auto;}
    .showcase-title-text{font-family:'Baloo 2',sans-serif;font-size:16px;color:var(--brown);line-height:1.35;}
    .showcase-title-note{font-family:Manrope,sans-serif;font-size:11px;font-weight:700;color:var(--terracotta);text-transform:uppercase;letter-spacing:.02em;}
    .showcase-title-logo.active, .showcase-title-text.active{opacity:1;}
    .phone-outline-stage{position:relative;padding:20px 0;}
    .phone-outline-glow{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:250px;height:250px;background:radial-gradient(circle, rgba(176,71,46,.22) 0%, rgba(176,71,46,0) 70%);border-radius:50%;z-index:0;}
    .phone-outline{width:220px;margin:0 auto;border:3px solid var(--brown);border-radius:38px;position:relative;padding:12px;background:var(--cream);box-shadow:0 26px 50px -12px rgba(66,40,27,.4), 0 10px 24px rgba(66,40,27,.16);transform:rotate(-3deg);animation:phoneFloat 4.5s ease-in-out infinite;z-index:1;}
    @keyframes phoneFloat{0%,100%{transform:rotate(-3deg) translateY(0);}50%{transform:rotate(-3deg) translateY(-10px);}}
    .phone-outline-notch{position:absolute;top:12px;left:50%;transform:translateX(-50%);width:56px;height:5px;border-radius:3px;background:var(--brown);z-index:2;}
    .phone-outline-screen{position:relative;height:380px;border-radius:26px;overflow:hidden;background:var(--brown);margin-top:14px;}
    .phone-outline-img{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:contain;object-position:center;opacity:0;transition:opacity .6s ease;}
    .phone-outline-img.active{opacity:1;}

    @media (max-width:640px){
      .deck-dots{display:none;}
      .deck-explore{font-size:11px;padding:6px 10px;}
    }
  </style>

  <script>
    (function() {
      var dots = document.querySelectorAll('.deck-dots .dot');
      var slides = document.querySelectorAll('.slide');
      var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) {
            var id = entry.target.id;
            dots.forEach(function(d) { d.classList.toggle('active', d.getAttribute('href') === '#' + id); });
          }
        });
      }, { threshold: 0.6 });
      slides.forEach(function(s) { io.observe(s); });

      var tabs = document.querySelectorAll('.folder-tab');
      var pages = document.querySelectorAll('.folder-page');
      tabs.forEach(function(tab) {
        tab.addEventListener('click', function() {
          var plan = tab.getAttribute('data-plan');
          tabs.forEach(function(t) { t.classList.toggle('active', t === tab); });
          pages.forEach(function(p) { p.classList.toggle('active', p.getAttribute('data-plan') === plan); });
        });
      });

      var phoneWrap = document.getElementById('phoneOutlineWrap');
      if (phoneWrap) {
        var sequence = [
          { view: 'logo', duration: 1400 },
          { view: 'web', duration: 3000 },
          { view: 'wallet', duration: 3000 },
        ];
        var seqIdx = 0;
        function showView(view) {
          phoneWrap.querySelectorAll('[data-view]').forEach(function(el) {
            el.classList.toggle('active', el.getAttribute('data-view') === view);
          });
        }
        function advance() {
          showView(sequence[seqIdx].view);
          setTimeout(function() {
            seqIdx = (seqIdx + 1) % sequence.length;
            advance();
          }, sequence[seqIdx].duration);
        }
        advance();
      }
    })();
  </script>
</body>
</html>`, { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
}

function renderSolicitudPage(url) {
  const plan = ['digital', 'fisico', 'wallet'].includes(url.searchParams.get('plan')) ? url.searchParams.get('plan') : '';
  const from = url.searchParams.get('from') === 'info' ? 'info' : 'web';
  const error = url.searchParams.get('error');
  const gracias = url.searchParams.get('gracias') === '1';

  const planLabel = plan === 'digital' ? 'Plan Fideliza Digital'
    : plan === 'fisico' ? 'Plan Fideliza Físico'
    : plan === 'wallet' ? 'Plan Fideliza Wallet' : '';

  const heading = from === 'info'
    ? (planLabel ? `Quiero el ${planLabel}` : 'Quiero contratar Hey Tapp')
    : 'Antes de ver los planes completos';
  const sub = from === 'info'
    ? 'Déjanos tus datos y te contactamos para dejar todo listo.'
    : 'Cuéntanos de tu marca y te llevamos directo a ver los 3 planes, con precios y todos los detalles.';

  const errorMsg = error === 'rate' ? 'Demasiados intentos. Espera unos minutos e intenta de nuevo.'
    : error ? decodeURIComponent(error) : '';

  const formOrThanks = gracias ? `
        <div class="contact-shell reveal" style="text-align:center;padding:40px 24px;">
          <h3 style="margin:0 0 10px;">¡Listo! 🎉</h3>
          <p class="contact-sub" style="margin:0;">Ya tenemos tus datos. Te contactamos en breve para dejar todo listo con tu ${planLabel || 'Hey Tapp'}.</p>
        </div>` : `
      <div class="contact-shell reveal">
        <div class="contact-form">
          <form id="solicitudForm" method="POST" action="/solicitud">
            <input type="hidden" name="from" value="${from}">
            ${errorMsg ? `<p class="form-msg err">${escapeHtml(errorMsg)}</p>` : ''}
            <div class="field">
              <label for="sf_name">Tu nombre</label>
              <input type="text" id="sf_name" name="name" required>
            </div>
            <div class="field-row">
              <div class="field">
                <label for="sf_phone">Celular</label>
                <input type="tel" id="sf_phone" name="phone" inputmode="numeric" placeholder="Ej. 0991234567" required>
                <p style="margin:6px 0 0;font-size:11.5px;color:var(--brown-soft);">Solo números, sin espacios ni guiones</p>
              </div>
              <div class="field">
                <label for="sf_email">Correo</label>
                <input type="email" id="sf_email" name="email" placeholder="nombre@correo.com" required>
              </div>
            </div>
            <div class="field">
              <label for="sf_instagram">Instagram de tu negocio</label>
              <input type="text" id="sf_instagram" name="instagram" placeholder="@tunegocio" required>
            </div>
            <div class="field">
              <label for="sf_type">¿Cuál plan te interesa?</label>
              <select id="sf_type" name="business_type">
                <option value="" ${!plan ? 'selected' : ''}>Elige tu tipo de negocio</option>
                <option value="digital" ${plan === 'digital' ? 'selected' : ''}>Plan Fideliza Digital</option>
                <option value="fisico" ${plan === 'fisico' ? 'selected' : ''}>Plan Fideliza Físico</option>
                <option value="wallet" ${plan === 'wallet' ? 'selected' : ''}>Plan Fideliza Wallet</option>
              </select>
            </div>
            <button type="submit" class="btn btn-primary">${from === 'info' ? 'Enviar' : 'Ver los planes →'}</button>
          </form>
        </div>
      </div>`;

  return new Response(`<!DOCTYPE html>
<html lang="es">
${pageHead(
  `${heading} — Hey Tapp`,
  sub,
  'https://heytapp.com/solicitud'
)}
<body>

${renderSiteNav('/')}

  <div class="wave-div" style="margin-top:64px;"><svg viewBox="0 0 1200 60" preserveAspectRatio="none"><rect x="0" y="0" width="1200" height="60" fill="#DAE7F1"></rect><path d="M0,0 C300,50 900,50 1200,0 L1200,60 L0,60 Z" fill="#FDFBF2" stroke="#FDFBF2" stroke-width="2"></path></svg></div>
  <section class="contact" id="solicitud" style="padding-top:56px;">
    <div class="wrap">
      <div class="eyebrow reveal">${from === 'info' ? '¡Ya casi!' : 'Antes de seguir'}</div>
      <h2 class="reveal">${escapeHtml(heading)}</h2>
      <p class="contact-sub reveal">${escapeHtml(sub)}</p>
      ${formOrThanks}
      <p class="reveal" style="text-align:center;margin-top:22px;font-size:12.5px;font-weight:700;letter-spacing:.4px;color:var(--brown-soft);">Made in Ecuador 🇪🇨 for the world</p>
    </div>
  </section>

  <div class="wave-div"><svg viewBox="0 0 1200 60" preserveAspectRatio="none"><rect x="0" y="0" width="1200" height="60" fill="#FDFBF2"></rect><path d="M0,0 C300,50 900,50 1200,0 L1200,60 L0,60 Z" fill="#42281B" stroke="#42281B" stroke-width="2"></path></svg></div>
${renderSiteFooter('/')}

  <script>
    const nav = document.getElementById('siteNav');
    nav.classList.add('scrolled');
    const burger = document.getElementById('burgerBtn');
    const mobileMenu = document.getElementById('mobileMenu');
    burger.addEventListener('click', () => { mobileMenu.classList.toggle('open'); burger.classList.toggle('open'); });
    mobileMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { mobileMenu.classList.remove('open'); burger.classList.remove('open'); }));
    document.querySelectorAll('.reveal').forEach(el => el.classList.add('in-view'));
    const phoneInput = document.getElementById('sf_phone');
    if (phoneInput) {
      phoneInput.addEventListener('input', (e) => {
        let onlyDigits = '';
        for (let i = 0; i < e.target.value.length; i++) {
          const code = e.target.value.charCodeAt(i);
          if (code >= 48 && code <= 57) onlyDigits += e.target.value[i];
        }
        e.target.value = onlyDigits;
      });
    }
  </script>
</body>
</html>`, { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
}


function renderContactPage() {
  return new Response(`<!DOCTYPE html>
<html lang="es">
${pageHead(
  'Pide información — Hey Tapp',
  'Cuéntanos de tu marca y te escribimos con los precios y todos los detalles de Hey Tapp.',
  'https://heytapp.com/contacto'
)}
<body>

${renderSiteNav('/')}

  <div class="wave-div" style="margin-top:64px;"><svg viewBox="0 0 1200 60" preserveAspectRatio="none"><rect x="0" y="0" width="1200" height="60" fill="#DAE7F1"></rect><path d="M0,0 C300,50 900,50 1200,0 L1200,60 L0,60 Z" fill="#FDFBF2" stroke="#FDFBF2" stroke-width="2"></path></svg></div>
  <section class="contact" id="contacto" style="padding-top:56px;">
    <div class="wrap">
      <div class="eyebrow reveal">Hablemos</div>
      <h2 class="reveal">Pide información</h2>
      <p class="contact-sub reveal">Déjanos tus datos y te enviaremos toda la información necesaria para que tu marca no pase nunca desapercibida.</p>
      <div class="contact-shell reveal">
        <div class="contact-form">
          <form id="leadForm">
            <div class="field">
              <label for="lf_name">Tu nombre</label>
              <input type="text" id="lf_name" required>
            </div>
            <div class="field-row">
              <div class="field">
                <label for="lf_phone">Celular</label>
                <input type="tel" id="lf_phone" inputmode="numeric" placeholder="Ej. 0991234567" required>
                <p style="margin:6px 0 0;font-size:11.5px;color:var(--brown-soft);">Solo números, sin espacios ni guiones</p>
              </div>
              <div class="field">
                <label for="lf_email">Correo</label>
                <input type="email" id="lf_email" placeholder="nombre@correo.com" required>
                <p style="margin:6px 0 0;font-size:11.5px;color:var(--brown-soft);">Debe incluir @ y un dominio (ej. correo.com)</p>
              </div>
            </div>
            <div class="field">
              <label for="lf_instagram">Instagram de tu negocio</label>
              <input type="text" id="lf_instagram" placeholder="@tunegocio" required>
            </div>
            <div class="field">
              <label for="lf_type">¿Cuál te interesa más?</label>
              <select id="lf_type">
                <option value="">Elige tu tipo de negocio</option>
                <option value="digital">Plan Fideliza Digital</option>
                <option value="fisico">Plan Fideliza Físico</option>
                <option value="wallet">Plan Fideliza Wallet</option>
              </select>
            </div>
            <button type="submit" class="btn btn-primary">Enviar</button>
          </form>
          <p class="form-msg" id="formMsg"></p>
        </div>
      </div>
      <p class="reveal" style="text-align:center;margin-top:22px;font-size:12.5px;font-weight:700;letter-spacing:.4px;color:var(--brown-soft);">Made in Ecuador 🇪🇨 for the world</p>
    </div>
  </section>

  <div class="wave-div"><svg viewBox="0 0 1200 60" preserveAspectRatio="none"><rect x="0" y="0" width="1200" height="60" fill="#FDFBF2"></rect><path d="M0,0 C300,50 900,50 1200,0 L1200,60 L0,60 Z" fill="#42281B" stroke="#42281B" stroke-width="2"></path></svg></div>
${renderSiteFooter('/')}

  <script>
    const nav = document.getElementById('siteNav');
    nav.classList.add('scrolled');

    const burger = document.getElementById('burgerBtn');
    const mobileMenu = document.getElementById('mobileMenu');
    burger.addEventListener('click', () => { mobileMenu.classList.toggle('open'); burger.classList.toggle('open'); });
    mobileMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { mobileMenu.classList.remove('open'); burger.classList.remove('open'); }));

    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReduced) {
      document.querySelectorAll('.reveal').forEach(el => el.classList.add('in-view'));
    } else {
      const io = new IntersectionObserver((entries) => {
        entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('in-view'); io.unobserve(entry.target); } });
      }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
      document.querySelectorAll('.reveal').forEach(el => io.observe(el));
    }

    document.getElementById('lf_phone').addEventListener('input', (e) => {
      let onlyDigits = '';
      for (let i = 0; i < e.target.value.length; i++) {
        const code = e.target.value.charCodeAt(i);
        if (code >= 48 && code <= 57) onlyDigits += e.target.value[i];
      }
      e.target.value = onlyDigits;
    });
    document.getElementById('leadForm').addEventListener('input', () => {
      const msg = document.getElementById('formMsg');
      if (msg.classList.contains('err')) { msg.textContent = ''; msg.className = 'form-msg'; }
    });
    document.getElementById('leadForm').addEventListener('submit', async (e) => {
      e.preventDefault();
      const msg = document.getElementById('formMsg');
      const payload = {
        name: document.getElementById('lf_name').value.trim(),
        phone: document.getElementById('lf_phone').value.trim(),
        email: document.getElementById('lf_email').value.trim(),
        instagram: document.getElementById('lf_instagram').value.trim(),
        business_type: document.getElementById('lf_type').value,
      };
      if (!payload.name || !payload.phone || !payload.email || !payload.instagram) {
        msg.textContent = 'Completa nombre, celular, correo e Instagram'; msg.className = 'form-msg err';
        return;
      }
      let phoneDigitsOnly = '';
      for (let i = 0; i < payload.phone.length; i++) {
        const code = payload.phone.charCodeAt(i);
        if (code >= 48 && code <= 57) phoneDigitsOnly += payload.phone[i];
      }
      payload.phone = phoneDigitsOnly;
      if (payload.phone.length === 0) {
        msg.textContent = 'El celular debe tener solo números'; msg.className = 'form-msg err';
        return;
      }
      const atPos = payload.email.indexOf('@');
      const lastAtPos = payload.email.lastIndexOf('@');
      const afterAt = atPos > -1 ? payload.email.slice(atPos + 1) : '';
      const dotPos = afterAt.lastIndexOf('.');
      const emailLooksValid = atPos > 0 && atPos === lastAtPos && payload.email.indexOf(' ') === -1
        && dotPos > 0 && dotPos < afterAt.length - 1;
      if (!emailLooksValid) {
        msg.textContent = 'Ingresa un correo válido (debe tener un @ y un dominio, ej. nombre@correo.com)'; msg.className = 'form-msg err';
        return;
      }
      msg.textContent = 'Enviando...'; msg.className = 'form-msg';

      // el aviso por correo ahora lo maneja solo el servidor (Resend primero,
      // FormSubmit de respaldo si Resend falla): antes el navegador también
      // le mandaba directo a FormSubmit por su cuenta, y cuando esa llamada
      // no lograba confirmar su propio éxito a tiempo, el servidor lo volvía
      // a mandar por Resend sin saberlo, y llegaban dos correos duplicados
      try {
        const res = await fetch('/contacto', {
          method: 'POST', headers: {'Content-Type':'application/json'},
          body: JSON.stringify(payload),
        });
        const data = await res.json();
        if (res.ok) {
          msg.textContent = '✅ ¡Listo! Te escribimos pronto a tu correo.'; msg.className = 'form-msg ok';
          document.getElementById('leadForm').reset();
        } else {
          msg.textContent = data.error || 'No se pudo enviar, intenta de nuevo'; msg.className = 'form-msg err';
        }
      } catch (err) {
        msg.textContent = 'Error de conexión, intenta de nuevo'; msg.className = 'form-msg err';
      }
    });
  </script>
</body>
</html>`, { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
}

